      <div class="table-wrap items-table"><table><thead><tr><th>Room type</th><th>How many</th><th>Typical replacement value per room ($)</th></tr></thead><tbody><tr><td>Bedrooms</td><td><input name="n-bed" inputmode="numeric" value="3" aria-label="Bedrooms count"></td><td><input name="v-bed" inputmode="decimal" value="9000" aria-label="Bedrooms value per room"></td></tr><tr><td>Bathrooms</td><td><input name="n-bath" inputmode="numeric" value="2" aria-label="Bathrooms count"></td><td><input name="v-bath" inputmode="decimal" value="2200" aria-label="Bathrooms value per room"></td></tr><tr><td>Kitchen</td><td><input name="n-kit" inputmode="numeric" value="1" aria-label="Kitchen count"></td><td><input name="v-kit" inputmode="decimal" value="16000" aria-label="Kitchen value per room"></td></tr><tr><td>Living / family rooms</td><td><input name="n-liv" inputmode="numeric" value="2" aria-label="Living / family rooms count"></td><td><input name="v-liv" inputmode="decimal" value="11000" aria-label="Living / family rooms value per room"></td></tr><tr><td>Dining room</td><td><input name="n-din" inputmode="numeric" value="1" aria-label="Dining room count"></td><td><input name="v-din" inputmode="decimal" value="6000" aria-label="Dining room value per room"></td></tr><tr><td>Office / den</td><td><input name="n-off" inputmode="numeric" value="1" aria-label="Office / den count"></td><td><input name="v-off" inputmode="decimal" value="7000" aria-label="Office / den value per room"></td></tr><tr><td>Garage / shop</td><td><input name="n-gar" inputmode="numeric" value="1" aria-label="Garage / shop count"></td><td><input name="v-gar" inputmode="decimal" value="12000" aria-label="Garage / shop value per room"></td></tr><tr><td>Patio, yard &amp; storage</td><td><input name="n-out" inputmode="numeric" value="1" aria-label="Patio, yard &amp; storage count"></td><td><input name="v-out" inputmode="decimal" value="5000" aria-label="Patio, yard &amp; storage value per room"></td></tr>
      </tbody></table></div>
      <div class="row2">
        <div><label for="c-lvl">How furnished is the home?</label><select id="c-lvl" name="lvl"><option value="0.7">Lightly</option><option value="1" selected>Typical</option><option value="1.4">Well furnished</option><option value="1.9">Extensively</option></select></div>
        <div><label for="c-yrs">Average age of belongings (years)</label><input id="c-yrs" name="yrs" inputmode="decimal" value="7"></div>
      </div>
      <div class="row2">
        <div><label for="c-a">Dwelling limit (Coverage A)</label><input id="c-a" name="cova" inputmode="decimal" value="420000"></div>
        <div><label for="c-c">Contents limit (Coverage C)</label><input id="c-c" name="covc" inputmode="decimal" value="210000"><span class="hint">Often 50% to 75% of the dwelling limit.</span></div>
      </div>
    </div>
    <div class="tool-out" aria-live="polite">
      <div class="out-big"><small>Estimated replacement cost of contents</small><b data-o="rcv">$0</b></div>
      <div class="out-big"><small>Rough actual cash value</small><b data-o="acv">$0</b></div>
